/* Public profiles have no account-setting or authentication-cache writes. */
'use strict';
(function(root){
const A=root.DCAccountCore,$=id=>document.getElementById(id);
const privateProfile=info=>[true,1,'1','true'].includes(info?.IsPrivate);
// Keyword matching belongs to the official index, not an exact-name comparison.
function searchPlan({query,type='player',mode='keyword',page=1}){const keyword=String(query??'').trim();if(!keyword)throw Error('请输入昵称关键字或 ID');if(keyword.length>80)throw Error('搜索内容过长');if(!['player','team','all'].includes(type)||!['keyword','name','id'].includes(mode))throw Error('搜索选项无效');if(mode==='id'){if(type==='all')throw Error('精确 ID 查询请选择玩家或战队');if(!/^\d+$/.test(keyword)||Number(keyword)<1||!Number.isSafeInteger(Number(keyword)))throw Error('ID 必须为正整数');return{path:type==='team'?'/api/Team/GetTeamInfo':'/api/User/GetInfo',params:type==='team'?{teamId:Number(keyword)}:{getNationRank:true,matchType:4,userId:Number(keyword)},direct:true,id:Number(keyword),type};}return{path:'/api/Common/Search',params:{keyword,type:type==='all'?0:type==='team'?2:1,page:Math.max(1,Math.floor(Number(page)||1)),pagesize:20},direct:false,type};}
function searchPage(data,plan){
 const valid=Array.isArray(data)||['List','list','Data','Items'].some(key=>Array.isArray(data?.[key]));
 if(!valid)throw Error('官方搜索返回格式无法识别，请稍后重试');
 const rows=A.list(data),seen=new Set(),items=[];
 for(const row of rows){if(!row||typeof row!=='object')continue;const type=Number(row.Type)===1?'player':Number(row.Type)===2?'team':plan.type==='all'?null:plan.type,id=Number(row.ID??row.UserID??row.TeamID);if(!type||plan.type!=='all'&&type!==plan.type||!Number.isSafeInteger(id)||id<=0)continue;const key=type+':'+id;if(seen.has(key))continue;seen.add(key);items.push({...row,ID:id,Type:type==='player'?1:2,Name:String(row.Name??row.UserName??row.TeamName??'未提供名称')});}
 const rawTotal=data?.RecordCount,total=rawTotal!==null&&rawTotal!==undefined&&rawTotal!==''&&Number.isFinite(Number(rawTotal))&&Number(rawTotal)>=0?Number(rawTotal):null;
 // Official UI continues until an empty page. A short page need not be the last.
 return{items,total,hasMore:rows.length>0&&(total===null||plan.params.page*plan.params.pagesize<total)};
}
function highlighted(name,keyword,e){const text=String(name),at=text.toLocaleLowerCase().indexOf(keyword.toLocaleLowerCase());return at<0?e(text):e(text.slice(0,at))+'<mark>'+e(text.slice(at,at+keyword.length))+'</mark>'+e(text.slice(at+keyword.length));}
function publicValues(info){return[['👥 所属战队',Number(info.TeamID)>0?info.TeamName||'战队 '+info.TeamID:'未提供'],['⚔️ 战力',info.LvRatio],['🏅 战绩',info.WinTimes],['🌏 全国总积分排名',info.RankNation===0?'未上榜':info.RankNation],['💠 总积分',info.MusicScore],['🎯 全连率',info.ComboPercent===null||info.ComboPercent===undefined?undefined:Number(info.ComboPercent)/100+'%']];}
function portrait(info,e){const face=A.mediaURL(info.HeadimgURL||info.HeadImgUrl),frame=A.mediaURL(info.HeadimgBoxPath),title=A.mediaURL(info.TitleUrl);return`<div class="profile-portrait ${title?'has-title':''}"><div class="portrait-face">${face?`<img src="${e(face)}" alt="公开头像" referrerpolicy="no-referrer">`:'♙'}</div>${frame?`<img class="portrait-frame" src="${e(frame)}" alt="公开头像框" referrerpolicy="no-referrer">`:''}${title?`<img class="portrait-title" src="${e(title)}" alt="公开称号" referrerpolicy="no-referrer">`:''}</div>`;}
async function render(h){const{request,esc:e,body,status,isCurrent}=h;let page=1,run=0,profileRun=0,lastPlan=null,hasMore=false,controller=null,busy=false;body().innerHTML=`<div class="account-list-heading"><h4>玩家 / 战队搜索</h4><span class="tiny-tag">公开资料 · 只读</span></div><form id="peopleForm" class="people-form"><label class="field">对象<select id="peopleType"><option value="player">玩家</option><option value="team">战队</option><option value="all">玩家和战队</option></select></label><label class="field">搜索方式<select id="peopleMode"><option value="keyword">昵称关键字</option><option value="id">精确 ID</option></select></label><label class="field people-query">关键字 / ID<input id="peopleQuery" type="search" maxlength="80" placeholder="输入昵称的一部分，如 小雾；数字也可作关键字" autocomplete="off" required></label><button id="peopleSubmit" type="submit" class="primary">搜索</button></form><p class="field-hint">输入昵称的一部分后按回车或搜索，按关键字查询官方索引；支持中文、外文、空格及数字昵称。精确 ID 请切换搜索方式。结果和匹配规则由官方服务提供。</p><div id="peopleResults" class="people-results" aria-live="polite"></div><div class="people-pagination"><button id="peoplePrev" disabled>← 上页</button><span id="peoplePage">等待搜索</span><button id="peopleNext" disabled>下页 →</button></div><div id="peopleProfile"></div>`;
const current=n=>isCurrent()&&n===run&&!!$('peopleResults'),profileCurrent=n=>isCurrent()&&n===profileRun&&!!$('peopleProfile');
function statsHTML(values){return values.filter(([,v])=>v!==null&&v!==undefined&&v!=='').map(([k,v])=>`<div><small>${e(k)}</small><b>${e(v)}</b></div>`).join('');}
function messageProfile(text){$('peopleProfile').innerHTML=`<section class="public-profile"><p class="account-note">${e(text)}</p></section>`;}
async function preview(id,type,provided){const n=++profileRun;if(!isCurrent())return;messageProfile('正在读取公开'+(type==='team'?'战队':'玩家')+'资料…');try{const info=provided||await request(type==='team'?'/api/Team/GetTeamInfo':'/api/User/GetInfo',{params:type==='team'?{teamId:id}:{getNationRank:true,matchType:4,userId:id}});if(!profileCurrent(n))return;if(!info||typeof info!=='object')throw Error('官方未返回有效资料');if(type==='team'){if(Number(info.TeamID)!==Number(id))throw Error('官方未返回该战队的可见资料');const logo=A.mediaURL(info.Logo);$('peopleProfile').innerHTML=`<section class="public-profile"><div class="account-profile">${logo?`<img class="public-team-logo" src="${e(logo)}" alt="战队标志" referrerpolicy="no-referrer">`:''}<div><h4>${e(info.TeamName||'战队 '+id)}</h4><p>ID ${id}${info.AddTime?' · 创建于 '+e(info.AddTime):''}</p></div></div><p class="account-note">${e(info.Intro||'暂无公开简介')}</p><div class="account-metrics">${statsHTML([['👥 成员',info.CurrentCount===undefined?undefined:info.CurrentCount+(info.MaxMember===undefined?'':' / '+info.MaxMember)],['🏷️ 战队等级',info.TeamLv],['💠 战队积分',info.TeamPoint],['🏆 战队排名',info.TeamRank]])}</div><button id="publicMembers">按需读取公开成员</button><div id="publicMemberRows" class="public-member-list"></div></section>`;$('publicMembers').onclick=async event=>{const button=event.currentTarget;button.disabled=true;try{const data=await request('/api/Team/GetTeamMemberList',{params:{teamId:id,orderby:0,ordertype:0,page:1,pagesize:20,getPointCurMonth:false}});if(!profileCurrent(n))return;const members=A.list(data);$('publicMemberRows').innerHTML=members.length?members.map(m=>`<button data-public-member="${e(m.UserID||'')}">${e(m.UserName||m.Name||'未提供名称')}<small> #${e(m.UserID||'—')}</small></button>`).join(''):'<p class="field-hint">官方未返回可见成员</p>';$('publicMemberRows').querySelectorAll('[data-public-member]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.publicMember)>0)preview(Number(b.dataset.publicMember),'player');});button.textContent='已读取前 '+members.length+' 位公开成员';}catch(err){if(profileCurrent(n))status('成员读取未完成：'+err.message);}finally{if(button.isConnected)button.disabled=false;}};return;}
if(Number(info.UserID)!==Number(id))throw Error('官方未返回该玩家的可见资料');const hidden=privateProfile(info);$('peopleProfile').innerHTML=`<section class="public-profile"><div class="account-profile profile-expanded">${portrait(info,e)}<div><h4>${e(info.UserName||'玩家 '+id)}</h4><p>ID ${id} · ${e(info.CityName||'地区未提供')}</p></div></div>${hidden?'<p class="account-note">🔒 该玩家的隐私设置限制资料展示。仅显示本次官方明确返回的基本资料，不继续请求成绩。</p>':`<div class="account-metrics">${statsHTML(publicValues(info))}</div>${Number(info.TeamID)>0?'<button id="publicTeam">查看所属战队</button> ':''}<button id="publicScores">按需读取公开成绩</button><div id="publicScoreRows"></div>`}</section>`;if($('publicTeam'))$('publicTeam').onclick=()=>preview(Number(info.TeamID),'team');if($('publicScores'))$('publicScores').onclick=async event=>{const button=event.currentTarget;button.disabled=true;try{const data=await request('/api/User/GetMyRankNew',{params:{userId:id,musicIndex:1,machineType:0}});if(!profileCurrent(n))return;const rows=A.list(data).slice(0,20);$('publicScoreRows').innerHTML=rows.length?'<div class="account-records">'+rows.map(row=>`<article><h5>${e(A.name(row))}</h5><p>歌曲 ID ${e(A.musicId(row)||'未提供')}${row.Score!==undefined?' · 分数 '+e(row.Score):''}${row.MusicLevel!==undefined?' · 等级 '+e(row.MusicLevel):''}</p></article>`).join('')+'</div>':'<p class="field-hint">官方未返回此分类的可见成绩</p>';button.textContent='已读取公开成绩（最多展示 20 条）';}catch(err){if(profileCurrent(n))status('成绩读取未完成：'+err.message);}finally{if(button.isConnected)button.disabled=false;}};
}catch(err){if(profileCurrent(n))messageProfile('资料读取未完成：'+err.message);}}
function pagination(){if(!$('peoplePrev'))return;$('peoplePrev').disabled=busy||!lastPlan||lastPlan.direct||page===1;$('peopleNext').disabled=busy||!lastPlan||lastPlan.direct||!hasMore;}
function invalidate(){run++;profileRun++;controller?.abort();controller=null;busy=false;lastPlan=null;hasMore=false;page=1;$('peopleResults').innerHTML='';$('peopleProfile').innerHTML='';$('peoplePage').textContent='条件已修改，请点击搜索';status('');pagination();}
async function search(reset=false,targetPage=1){
 let plan;try{plan=reset?searchPlan({query:$('peopleQuery').value,type:$('peopleType').value,mode:$('peopleMode').value,page:1}):lastPlan&&!lastPlan.direct?{...lastPlan,params:{...lastPlan.params,page:targetPage}}:null;if(!plan)return;}catch(err){invalidate();status(err.message);return;}
 const n=++run;profileRun++;controller?.abort();controller=new AbortController();busy=true;pagination();$('peopleResults').setAttribute('aria-busy','true');$('peopleResults').innerHTML='<p class="field-hint">正在查询官方服务…</p>';$('peopleProfile').innerHTML='';status('');
 try{const data=await request(plan.path,{params:plan.params,signal:controller.signal});if(!current(n))return;
 if(plan.direct){lastPlan=plan;page=1;hasMore=false;$('peopleResults').innerHTML='';$('peoplePage').textContent='精确 ID '+plan.id;await preview(plan.id,plan.type,data);}
 else{const result=searchPage(data,plan),items=result.items;lastPlan=plan;page=plan.params.page;hasMore=result.hasMore;
 $('peopleResults').innerHTML=items.length?items.map((item,i)=>{const image=A.mediaURL(item.HeadimgURL),kind=item.Type===1?'玩家':'战队';return`<button class="people-result" data-people-index="${i}">${image?`<img src="${e(image)}" referrerpolicy="no-referrer" loading="lazy" alt="公开头像">`:'♙'}<span><b>${highlighted(item.Name,plan.params.keyword,e)}</b><small>${kind} · ID ${e(item.ID)}${item.Region?' · '+e(item.Region):''}</small>${item.Type===1&&item.LvRatio!==undefined?`<small>⚔️ 战力 ${e(item.LvRatio)}</small>`:''}</span></button>`;}).join(''):'<p class="empty-state">'+(page===1?'没有找到匹配项。可缩短昵称关键字、切换玩家和战队，或使用精确 ID。':'已到结果末尾，可返回上页。')+'</p>';
 $('peopleResults').querySelectorAll('[data-people-index]').forEach(b=>b.onclick=()=>{const item=items[Number(b.dataset.peopleIndex)];preview(item.ID,item.Type===1?'player':'team');});$('peoplePage').textContent='“'+plan.params.keyword+'” · 第 '+page+' 页 · 本页 '+items.length+' 项'+(result.total===null?'':' · 共 '+result.total+' 项');}
 }catch(err){if(current(n)){$('peopleResults').innerHTML='<p class="empty-state">查询未完成：'+e(err.message)+'</p><button id="peopleRetry">重试本次查询</button>';$('peopleRetry').onclick=()=>{if(reset)search(true);else search(false,targetPage);};$('peoplePage').textContent='请求失败，不代表没有结果';status(err.message);}}
 finally{if(current(n)){busy=false;$('peopleResults').setAttribute('aria-busy','false');pagination();}}
}
$('peopleForm').onsubmit=event=>{event.preventDefault();search(true);};$('peopleQuery').oninput=invalidate;$('peopleType').onchange=invalidate;$('peopleMode').onchange=()=>{invalidate();$('peopleQuery').placeholder=$('peopleMode').value==='id'?'输入完整的正整数 ID':'输入昵称的一部分，如 小雾；数字也可作关键字';};$('peoplePrev').onclick=()=>{if(!busy&&page>1)search(false,page-1);};$('peopleNext').onclick=()=>{if(!busy&&hasMore)search(false,page+1);};

}
root.DCAccountPeople={render,searchPlan,searchPage,privateProfile,publicValues};
})(typeof window==='undefined'?globalThis:window);
